import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.DPTJCqgd.js";const p=JSON.parse('{"title":"Use the Web UI","description":"","frontmatter":{"editSource":"docs/user/guide/index.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/c5ef947d98383a25f1481671f55bfda8e92b1a82/docs/user/guide/index.md"},"headers":[],"relativePath":"en/guide/quickstart.md","filePath":"en/guide/quickstart.md"}'),s={name:"en/guide/quickstart.md"};function i(n,e,d,h,l,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="use-the-web-ui" tabindex="-1">Use the Web UI <a class="header-anchor" href="#use-the-web-ui" aria-label="Permalink to &quot;Use the Web UI&quot;">​</a></h1><p>Start the Web UI through the <a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/c5ef947d98383a25f1481671f55bfda8e92b1a82/README.md#run" target="_blank" rel="noreferrer">root README</a>; the command prints its URL. This guide begins after that server is running. The <code>dsh</code> process uses its invoking directory as the default filesystem location, but a fresh Web UI has no selected workspace until you add one.</p><h2 id="configure-a-model" tabindex="-1">Configure a model <a class="header-anchor" href="#configure-a-model" aria-label="Permalink to &quot;Configure a model&quot;">​</a></h2><p>Open <strong>Settings → Models</strong>, enter a <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek API key</a>, and save it. The model route becomes usable immediately without restarting the server.</p><p>The <a href="./providers">model configuration guide</a> covers other providers and custom OpenAI-compatible endpoints.</p><h2 id="choose-a-workspace" tabindex="-1">Choose a workspace <a class="header-anchor" href="#choose-a-workspace" aria-label="Permalink to &quot;Choose a workspace&quot;">​</a></h2><p>Click <strong>Choose workspace</strong>, add the project directory where you started <code>dsh</code>, and select it. The session composer remains unavailable until a workspace is selected.</p><h2 id="run-a-task" tabindex="-1">Run a task <a class="header-anchor" href="#run-a-task" aria-label="Permalink to &quot;Run a task&quot;">​</a></h2><p>Start a session and send:</p><blockquote><p>Summarize this repository and identify its main packages.</p></blockquote><p>The agent can read and edit workspace files, run commands, delegate work, and maintain a plan. The Web UI asks before operations that require approval under the active permission policy.</p><h2 id="continue" tabindex="-1">Continue <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;Continue&quot;">​</a></h2><ul><li><a href="./providers">Configure models</a></li><li><a href="./python-sdk">Use the Python SDK</a></li><li><a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/c5ef947d98383a25f1481671f55bfda8e92b1a82/apps/cli/README.md" target="_blank" rel="noreferrer">Use other CLI modes</a></li><li><a href="./../develop/basic/">Develop a plugin</a></li></ul>',13)])])}const b=a(s,[["render",i]]);export{p as __pageData,b as default};
